import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(N + 1)]

    for _ in range(M):
        try:
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)
        except StopIteration:
            break

    if N == 1:
        print(0)
        return

    disc = [-1] * (N + 1)
    low = [-1] * (N + 1)
    parent = [-1] * (N + 1)
    ap_count = 0
    timer = 0
    visited_count = 0

    def dfs(u):
        nonlocal timer, visited_count, ap_count
        visited_count += 1
        disc[u] = low[u] = timer
        timer += 1
        children = 0

        for v in adj[u]:
            if disc[v] == -1:
                children += 1
                parent[v] = u
                dfs(v)
                low[u] = min(low[u], low[v])

                if parent[u] != -1 and low[v] >= disc[u]:
                    if not hasattr(dfs, 'ap_set'):
                        dfs.ap_set = set()
                    if u not in dfs.ap_set:
                        dfs.ap_set.add(u)
                        ap_count += 1
            elif v != parent[u]:
                low[u] = min(low[u], disc[v])

        if parent[u] == -1 and children > 1:
            if not hasattr(dfs, 'ap_set'):
                dfs.ap_set = set()
            if u not in dfs.ap_set:
                dfs.ap_set.add(u)
                ap_count += 1

    dfs.ap_set = set()

    dfs(1)

    if visited_count < N:
        print(0)
    else:
        print(ap_count)

if __name__ == "__main__":
    main()
